.stat-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  border: 1px solid var(--color-border-default, #d4d4d4);
  border-radius: var(--radius-md, 8px);
  background: var(--color-surface-default, #fff);
  color: var(--color-text-primary, #0a0a0a);
  max-width: 260px;
}
.stat-card__label { font-size: 12px; line-height: 16px; color: var(--color-text-secondary, #404040); }
.stat-card__value { font-size: 32px; line-height: 40px; font-weight: 700; letter-spacing: -0.01em; }
.stat-card__trend { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; line-height: 16px; font-weight: 600; color: #166534; }
.stat-card__trend--down { color: #991b1b; }
.stat-card a:focus-visible, .stat-card:focus-visible { outline: 2px solid #1d4ed8; outline-offset: 2px; }
